import { View, Text } from 'react-native'
import React, { useEffect, useRef } from 'react'
import { BackgroundImageContainer } from '../components/backgroundImage/BackgroundImageContainer';
import { ActionButton, BottomSheet, BottomSheetManager, BottomSheetRef, createStyles, GradientButton, PortalManager } from '@core/ui';
import { useTranslation } from '@core/service';
import LottieView from 'lottie-react-native';
import { BellNotification } from '@src/assets/lottie';
import { useRoute } from '@react-navigation/native';

type Button = {
    lable: string;
    onPress?: () => void;
    isShow: boolean;
}
type Icon = {
    isShow: boolean;
    source?: any;
}
export type NotifyProps = {
    id?: string;
    title: string;
    content: string;
    primaryButton?: Button;
    secondaryButton?: Button;
    icon?: Icon;
    type?: 'default' | 'gradient';
};
const NotifyScreen = () => {
    const route: any = useRoute();
    const props: NotifyProps = route?.params?.data || '';
    const {
        id = 'common-information',
        title = 'Thông báo',
        content = 'Hành trình đăng ký mở tài khoản của Quý khách đã bị dừng/gián đoạn. Quý khách có muốn tiếp tục hành trình trước đó không?',
        primaryButton = { isShow: true, lable: 'Tiếp tục thực hiện' },
        secondaryButton = { isShow: true, lable: 'Bỏ qua' },
        icon = { isShow: true }
    } = props;
    const styles = useStyles();
    const { t } = useTranslation(['common']);
    const bottomSheetRef = useRef<BottomSheetRef>(null);
    useEffect(() => {
        BottomSheetManager.show({
            render: (portalId) => (
                <BottomSheet
                    id={id}
                    ref={bottomSheetRef}
                    allowToDismiss={false}
                >
                    {/* <ConfirmNotification
                    title={t('unclearTitle')}
                    content={t('nfcScanNotClear.unclearNfcDes')}
                    primaryButtonOnPress={() => {
                        PortalManager.dismissAll();
                        openCheckNFC();
                    }}
                    primaryButtonText={t('retryText')}
                /> */}
                    <View style={[styles.shareContainer]}>
                        {icon?.isShow &&
                            <LottieView
                                source={icon.source || BellNotification}
                                style={styles.icon}
                                autoPlay
                                loop
                            />
                        }
                        {title && <Text style={styles.titleStyle}>{title}</Text>}
                        {content && (
                            <Text style={styles.contentStyle}>
                                {content}
                            </Text>
                        )}
                        {secondaryButton.isShow && (
                            <ActionButton
                                style={styles.buttonSecondaryStyle}
                                type="secondary"
                                size="large"
                                title={secondaryButton.lable || t('cancel')}
                                onPress={secondaryButton.onPress}
                            />
                        )}
                        {primaryButton.isShow &&
                            <GradientButton
                                gradientProps={{ type: 'primary' }}
                                // size="large"
                                // buttonStyle={styles.secondaryButtonStyle}
                                title={primaryButton.lable || t('ok')}
                                onPress={primaryButton.onPress}
                            />
                        }
                    </View>
                </BottomSheet>
            )
        })
    }, []);
    return (
        <BackgroundImageContainer></BackgroundImageContainer>
    );
};

const useStyles = createStyles((theme) => ({
    shareContainer: {
        margin: theme.Size.Vertical.Medium,
        paddingVertical: theme.Size.Vertical.Base,
        backgroundColor: 'transparent',
    },
    icon: {
        aspectRatio: 1,
        width: theme.Size.Horizontal.Colossal,
    },
    titleStyle: {
        fontSize: theme.Size.ms(24),
        fontWeight: 600,
        marginBottom: theme.Size.Vertical.Base,
        marginTop: theme.Size.Vertical.Base,
    },
    contentStyle: {
        marginBottom: theme.Size.Vertical.xxLarge,
    },
    buttonStyle: {
        height: theme.Size.Vertical.ExtraLarge - 3,
        paddingTop: theme.Size.vs(12),
        paddingBottom: theme.Size.vs(12),
    },
    secondaryButtonStyle: {
        marginTop: theme.Size.Vertical.Base,
    },
    buttonTextStyle: {
        fontWeight: 600,
    },
    buttonSecondaryStyle: {
        marginBottom: theme.Size.Vertical.Base,
    }
}));

export default NotifyScreen