import {
  eventBusService,
  formatDateFDash2Splash,
  isLessThan18YearsOld,
  isValidIdExpiryDate,
} from '@core/service';
import { DOCUMENT_VERIFY } from '@src/config';
import {
  HVDocumentResponse,
} from '@src/domain/entities/hyperV/ekyc';
import { useState } from 'react';
import { DOCUMENT_STATUS, DOCUMENT_TYPE, PortalManager } from '@core/ui';
import { extractBirthDayExpireDayFromDocument } from '@src/utils/ekyc';
import { useDispatch } from 'react-redux';
import { updateICData } from '@src/presentation/dop_ocr/redux/slice';
import { updateValidateOCRData } from "@src/presentation/redux/slice";
// import { getOnboardingId } from '@src/presentation/onboarding/components/PhoneRegister/selector';
import { useSelector } from '@src/lib/redux';
// import { useNavigate } from '@src/hooks/useNavigate';
import { useTranslation } from 'react-i18next';
import goToScreen from '@src/utils/goToLoginScreen';
import { useCustomNavigation } from './useCustomNavigation';
import { convertImgToBase64 } from '@src/utils/share-view-shot';

const useScanICService = () => {
  const [isReady, setReady] = useState<boolean>(false);
  // const onboardingId = useSelector(getOnboardingId);
  const onboardingId = 'transactionIdfortestEkyc';
  const { t } = useTranslation(['ekyc']);
  const { navigate, navigateAndReplace, goBackFromNativeModules, navigateAndReset } = useCustomNavigation();
  const dispatch = useDispatch();

  const onScanIC = () => {
    scanIC(onboardingId! || 'transactionIdfortestEkyc').catch();
  };
  const scanIC = async (onboardingId: string) => {
    eventBusService.emit('open_app', {
      appName: 'HypervergeApp',
      screen: 'IdCardScanSavedScreen',
      data: {
        transactionId: onboardingId,
        workflowId: DOCUMENT_VERIFY,
        callback: (resultData: object) => {
          console.log('\x1b[31m phapv7_resultData_scan_ic', resultData);
          const result = resultData as HVDocumentResponse;
          return onScanICCompleted(resultData as any);
        },
      },
    });
  };

  const onHandleNegativeScanICResult = () => {
    navigate('notify_screen', {
      data: {
        id: 'common-information',
        title: t('onScan.unclear_title'),
        content: t('onScan.scan_unclear.unclear_des'),
        primaryButton: {
          isShow: true,
          lable: t('onScan.retry_text'),
          onPress: () => {
            PortalManager.dismissAll();
            navigate('EKYC_identity_card')
          }
        }
      },
    });
  };
  const onHandlePositiveScanICResult = async (result: HVDocumentResponse) => {
    try {
      const { idNumber = '', idType } = result.details || ({} as any);
      if (!idNumber) {
        onHandleNegativeScanICResult();
        return;
      }
      const { expireDay = '' } = extractBirthDayExpireDayFromDocument(
        result.details,
      );
      if (!isValidIdExpiryDate(expireDay)) {
        navigate('notify_screen', {
          data: {
            id: 'expire-cccd-bottomsheet',
            title: t('onScan.unclear_title'),
            content: t('onScan.scan_unclear.expired_CCCD'),
            primaryButton: {
              isShow: true,
              lable: t('onScan.retry_text'),
              onPress: () => {
                PortalManager.dismissAll();
                navigate('EKYC_identity_card')
              }
            }
          },
        });
        return;
      }

      // under age
      const { birthDay = '' } = extractBirthDayExpireDayFromDocument(
        result.details,
      );
      if (isLessThan18YearsOld(birthDay)) {
        navigate('notify_screen', {
          data: {
            id: 'under-age-bottomsheet',
            title: t('onScan.unclear_title'),
            content: t('onScan.under_age_title'),
            primaryButton: {
              isShow: true,
              lable: t('onScan.understood'),
              onPress: () => {
                goToScreen({ appName: 'AuthApp', screen: 'LoginUsername' });
              }
            }
          },
        });

        return;
      }
      setReady(true);
      const document = result.details;
      convertImgToBase64(document.frontImage || '');
      dispatch(updateICData(document));
      const backImg = await convertImgToBase64(document?.backImage || '');
      const frontImg = await convertImgToBase64(document?.frontImage || '');
      dispatch(updateValidateOCRData({
        identityNumber: document?.idNumber || '',
        idCardNoOcr: document?.idNumber || '',
        expireDate: formatDateFDash2Splash(document?.dateOfExpiry || '') || '',
        isEkyc: 'Y',
        dob: formatDateFDash2Splash(document?.dateOfBirth || '') || '',
        idCardTypeOcr: document?.idType || '',
        issuedBy: document?.placeOfIssue || '',
        nationality: document?.nationality || '',
        fullName: document?.name || '',
        addrDetail: document?.address || '',
        identityType: document?.idType || '',
        gender: document?.gender || '',
        issuedDate: formatDateFDash2Splash(document?.dateOfIssue || '') || '',
        frontId: frontImg,
        backId: backImg,
      }))
      if (idType === DOCUMENT_TYPE.cc24_front) {
        // request scan QR code
        // navigate('ScanQRScreen');
      } else {
        navigate('EKYC_identity_card_result');
      }
    } catch {
      onHandleNegativeScanICResult();
    }
  };
  const onScanICCompleted = async (res: object) => {
    const result = res as HVDocumentResponse;
    try {
      switch (result.status) {
        case DOCUMENT_STATUS.USER_CANCELLED:
          goBackFromNativeModules();
          break;
        case DOCUMENT_STATUS.AUTO_APPROVED:
        case DOCUMENT_STATUS.NEEDS_REVIEW:
          await onHandlePositiveScanICResult(result);
          break;
        case DOCUMENT_STATUS.AUTO_DECLINED:
          // navigate('EKYCIDScanUnclear');
          break;
        case DOCUMENT_STATUS.ERROR:
        default:
          onHandleNegativeScanICResult();
          break;
      }
    } catch (err) {
      console.error('Error in onDocumentScanCompleted:', err);
    }
  };
  return {
    isReady,
    onScanIC,
  };
};

export { useScanICService };
