const NFCGuidelineImgBuilder = ''
const guidelinesDeviceImageBuilder = (brand: string, model: string) => {
    if (!brand || !model) {
        return null;
    }

    const _brand = brand.toUpperCase();
    let _name = model.toUpperCase();

    if (IS_ANDROID) {
        const marketingName =
            (listAndroidNFCDeviceGuidelines as any)?.[_brand]?.[_name] ?? '';
        _name = marketingName;
    }
    if (_name) {
        return {
            url: `${NFCGuidelineImgBuilder}${_brand}-${_name.replaceAll(
                ' ',
                '-',
            )}.png`,
            name: _name,
        };
    }
};

const NFCGuidelines: React.FC<{
    title?: string;
    description?: string;
    style?: StyleProp<ViewStyle>;
    showWarning?: boolean;
    iconSize?: 'large' | 'small';
}> = () => {
    const { t } = useTranslation(['nfc']);
    const { theme } = useTheme();
    const { Colors, GradientColors } = theme;
    const styles = useStyles();
    const [deviceInfo, setDeviceInfo] = useState<{
        brand: string;
        model: string;
    }>({ brand: '', model: '' });
    const [guideLine, setGuideLine] = useState<{
        url: string;
        name: string;
    } | null>(null);
    const [isFetching, setIsFetching] = useState(false);

    useEffect(() => {
        const fetchDeviceInfo = async () => {
            await Device.init();
            setDeviceInfo({
                brand: Device.INFO.brand.toString(),
                model: Device.INFO.model.toString(),
            });

            setIsFetching(true);
        };
        fetchDeviceInfo();
    }, []);
    useEffect(() => {
        if (isFetching && deviceInfo.brand && deviceInfo.model) {
            const guidelineData = guidelinesDeviceImageBuilder(
                deviceInfo.brand,
                deviceInfo.model,
            );
            if (guidelineData) {
                setGuideLine(guidelineData);
                setIsFetching(false);
            }
        }
    }, [isFetching, deviceInfo]);

    const renderImageGuidelines = () => {
        // if (!guideLine?.url) {
        //   return (
        //     <View style={styles.iconContainer}>
        //       <LottieView source={NFCGuideline} style={styles.icon} autoPlay loop />
        //     </View>
        //   );
        // }

        return (
            <View style={styles.imageGuidelinesContainer}>
                <View style={styles.nidCardContainer}>
                    <FastImage source={NIDCard} style={styles.nidCardImg} />
                    <Text style={styles.imgDesText}>{t('guide_line.img_desc')}</Text>
                </View>
                <View style={styles.deviceContainer}>
                    <View style={styles.deviceImageContainer}>
                        <FastImage
                            resizeMode="contain"
                            source={require('@src/assets/images/pixelMobile.png')}
                            // source={{
                            //   uri: '@assets/images/pixelMobile.png',
                            // }}
                            style={styles.deviceImg}
                        />
                        {/* <View style={styles.deviceImageLayer} /> */}
                    </View>
                    <Text style={styles.imgDeviceText}>{deviceInfo?.brand}</Text>
                </View>
            </View>
        );
    };
    return (
        <View style={styles.container}>
            {renderImageGuidelines()}
        </View>
    );
};

