import React, { useEffect, useState } from 'react';
import { StyleProp, Text, TextStyle, TouchableOpacity, View, ViewStyle } from 'react-native';
import { ICheckedBoxSmall, useTheme } from '@core/ui';
import useStyles from './styles';

interface RatioTypes {
    checked: boolean;
    onChange: () => void;
    disabled?: boolean;
    label?: string;
    isDotIcon?: boolean;
    textStyle?: StyleProp<TextStyle>;
    containerStyle?: StyleProp<ViewStyle>;
    dotStyle?: StyleProp<ViewStyle>;
    activeColor?: string;
}

const Ratio = ({ checked, onChange, disabled = false, label, isDotIcon = true, textStyle, containerStyle, dotStyle, activeColor }: RatioTypes) => {
    const { theme } = useTheme();
    const styles = useStyles();
    const [check, setCheck] = useState(false);

    useEffect(() => {
        setCheck(checked);
    }, [checked]);

    return (
        <TouchableOpacity style={[styles.root, containerStyle]} onPress={() => onChange?.()} disabled={disabled}>
            <View
                style={[
                    styles.border,
                    { borderColor: check ? theme.Colors.Text.Neutral600 : theme.Colors.Border.Neutral500 },
                    !isDotIcon && check && { padding: 0, borderWidth: 0 },
                    dotStyle,
                ]}>
                {check && (
                    <View
                        style={[
                            styles.dot,
                            !isDotIcon && { width: '100%', height: '100%', borderRadius: 999, justifyContent: 'center', alignItems: 'center' },
                            activeColor && { backgroundColor: activeColor },
                        ]}>
                        {!isDotIcon && <ICheckedBoxSmall fill={theme.Colors.Base.White} />}
                    </View>
                )}
            </View>
            {label && <Text style={[styles.label, textStyle]}>{label}</Text>}
        </TouchableOpacity>
    );
};

export default Ratio;
