import { View, Text, ScrollView } from 'react-native'
import React, { useEffect } from 'react'
import { BackgroundImageContainer } from '@src/presentation/components/backgroundImage/BackgroundImageContainer'
import StepHeader from '../components/header/StepHeader'
import useCSS from '@src/presentation/style'
import { BaseButton, createStyles, GradientButton, LoadingBlockerView, useTheme } from '@core/ui'
import HighlightTitle from '@src/presentation/components/text/HighlightTitle'
import { useTranslation } from '@core/service'
import AnimatedLottieView from 'lottie-react-native';
import { ProgressFrontLoop } from '@src/assets/lottie'
import { Guidelines } from '@src/presentation/components/guideLine'
import { useCustomNavigation } from '@src/hooks/useCustomNavigation'
import { useDispatch } from '@src/lib/redux'
import { fetchBiometricInfo } from '../thunk'
import { CardDOPBaseResponse } from '@src/domain/entities/common/cardDOPBaseApi'
import { BiometricInfoDataRes } from '@src/domain/entities/card_dop/biometricInfo'
import { useSelector } from 'react-redux'
import { selectIsLoading } from '../redux/selector'
import { useScanFaceService } from '@src/hooks/useScanFaceService'

const EKYCIdentityCardResultScreen = () => {
    const css = useCSS()
    const styles = useStyles();
    const { t } = useTranslation(['ekyc'])
    const isLoading = useSelector(selectIsLoading)
    const { navigate } = useCustomNavigation();
    const dispatch = useDispatch();
    const { onVerifyFace } = useScanFaceService();
    useEffect(() => {
        dispatch(fetchBiometricInfo()).then(res => {
            const resp = (res.payload as CardDOPBaseResponse<BiometricInfoDataRes>)
            if (resp?.resultCode === '00') {
                let isExisted = resp?.data.biometricExisted
                if (!isExisted) {
                    navigate('EKYC_face')
                } else {
                    onVerifyFace(resp.data.userId, resp.data.biometricKey)
                }
            }
        })
        // setTimeout(() => {
        //     navigate('EKYC_face')
        // }, 500);
    }, [])

    return (
        <BackgroundImageContainer>
            {isLoading && <LoadingBlockerView containerStyle={{ backgroundColor: 'rgba(255,255,255,0.5)', zIndex: 100000 }} />}
            <StepHeader logo={true} progress={{ current: 2, total: 5 }} />
            <View style={styles.container}>
                <ScrollView bounces={false} showsVerticalScrollIndicator={false}>
                    <View style={styles.titleHeader}>
                        <HighlightTitle
                            title={t('ekyc_ic.result_success')}
                            subtitle={t('ekyc_ic.result_waiting')}
                        />
                    </View>
                    <AnimatedLottieView
                        loop
                        autoPlay
                        style={styles.icon}
                        source={ProgressFrontLoop}
                    />
                </ScrollView>
            </View>
        </BackgroundImageContainer>
    )
}
