import {inject} from 'inversify';
import {TYPES} from '@src/di/types/types';
import {Query} from '@src/domain/models/query';
import { CardDOPBaseRequest } from '@src/domain/entities/common/cardDOPBaseApi';
import type { IAddCardInfoRepository } from '@src/domain/interfaces/card_dop/addCardInfo';
import { AddCardInfoDataReq } from '@src/domain/entities/card_dop/addCardInfo';

export class AddCardInfoHandler {
    private readonly _repository: IAddCardInfoRepository;

    constructor(
        @inject(TYPES.IAddCardInfoRepository)
        addCardInfoRepository: IAddCardInfoRepository
    ) {
        this._repository = addCardInfoRepository;
    }

    handle(query: Query<CardDOPBaseRequest<AddCardInfoDataReq>>) {
        return this._repository.addCardInfo(query);
    }
}
