import { eventBusService } from '@core/service';
import { OpenAppPayloadOnboarding } from '@src/domain/entities/hyperV/ekyc';

const goToScreen = ({ appName, screen }: OpenAppPayloadOnboarding) => {
  eventBusService.emit<OpenAppPayloadOnboarding>('open_app', {
    appName: appName,
    screen: screen,
  });
};

export default goToScreen;
