import React, { useEffect, useState } from 'react';
import { SafeAreaView, ScrollView, View, ImageBackground, TouchableOpacity } from 'react-native';
import { GradientButton, LoadingBlockerView, Spacer, Text, MaterialTextInput, SimpleHeader } from '@core/ui';
import useCSS from '@src/presentation/style';
import { useNavigation } from '@react-navigation/native';
import { MainStackNavigationProp } from '@src/presentation/navigation/MainNavigator';
import { useTranslation } from 'react-i18next';
import PasswordInput from '../components/passwordInput';
import { fetchAuthUser, fetchGetAuthPublicKey } from './thunk';
import { LOGIN_DOP } from '@src/utils/constants';
import { CardDOPBaseRequest, CardDOPBaseResponse } from '@src/domain/entities/common/cardDOPBaseApi';
import { GetAuthPublicKeyDataReq, GetAuthPublicKeyDataRes } from '@src/domain/entities/card_dop/getAuthPublicKey';
import { useDispatch, useSelector } from '@src/lib/redux';
import { encryptPasswordRSA, formatPublicKeyPEM } from '@src/utils/common';
import { AuthUserDataReq, AuthUserDataRes } from '@src/domain/entities/card_dop/authUser';
import { selectStatus } from './redux/selector';

const DOPLoginScreen = () => {
    const css = useCSS();
    const navigation = useNavigation<MainStackNavigationProp>();
    const { t } = useTranslation(['module_dop']);
    const dispatch = useDispatch();

    const status = useSelector(selectStatus);
    const [username, setUsername] = useState('');
    const [password, setPassword] = useState('');
    const [disabled, setDisabled] = useState(true);

    useEffect(() => {
        if (username && password) {
            setDisabled(false);
        } else {
            setDisabled(true);
        }
    }, [username, password]);

    const handleSubmit = () => {
        if (disabled) {
            return;
        }
        dispatch(
            fetchGetAuthPublicKey({
                partnerId: LOGIN_DOP,
            } as CardDOPBaseRequest<GetAuthPublicKeyDataReq>['data']),
        )
            .then((res) => {
                const publicKey = (res.payload as CardDOPBaseRequest<GetAuthPublicKeyDataRes>)?.data?.publicKey;

                //Bước 2: Mã hóa user và password do người dùng nhập
                const credential = encryptPasswordRSA(`{ username: ${username}, password: ${password} }`, formatPublicKeyPEM(publicKey));
                console.log('\x1b[31m thieuvq3 credential: ', credential);

                dispatch(
                    fetchAuthUser({
                        leadId: 'e2ab87bf07032025', //lay trong store
                        clientNo: '20017963', //lay trong store
                        key: publicKey,
                        partnerId: LOGIN_DOP,
                        userId: '0901114823', //lay trong store
                        credential: credential,
                    } as CardDOPBaseRequest<AuthUserDataReq>['data']),
                )
                    .then((respone) => {
                        const payload = respone.payload as CardDOPBaseResponse<AuthUserDataRes>;
                        console.log('thieuvq3 respone: ', JSON.stringify(payload?.data?.accts || [], null, 4));
                        navigation.navigate('dop_credit_card_screen');
                    })
                    .catch((ex) => {
                        console.log('thieuvq3 ex: ', ex);
                    });
            })
            .catch((ex) => {
                console.log('thieuvq ex fetchGetAuthPublicKey: ', ex);
            });
    };

    return (
        <ImageBackground source={require('@src/assets/images/bg_body.jpg')} resizeMode='cover' style={[css.flex_1]}>
            <SafeAreaView style={[css.flex_1]}>
                <SimpleHeader title={t('screen_password.login')} allowGoBack={true} onBackPress={() => navigation.goBack()} />
                {status === 'loading' ? <LoadingBlockerView containerStyle={{ backgroundColor: 'rgba(255,255,255,0.5)', zIndex: 100000 }} /> : null}
                <ScrollView showsHorizontalScrollIndicator={false} showsVerticalScrollIndicator={false}>
                    <View style={[css.flex_1, css.mt_xLarge, css.mh_medium]}>
                        <Text style={[css.text_title_200, css.font_semibold, css.text_black, css.mt_small]}>
                            {t('screen_password.welcome')}{' '}
                            <Text style={[css.text_title_200, css.font_semibold, css.text_red_600]}>{t('screen_password.return')},</Text>
                            {' \n'}
                            {t('screen_password.login_to_continue')}
                        </Text>
                        <Spacer height={24} />
                        <MaterialTextInput label={t('screen_password.username')} value={username} onChangeText={setUsername} style={css.mv_base} />
                        <Spacer height={16} />
                        <PasswordInput label={t('screen_password.password')} value={password} onChangeText={setPassword} style={css.mv_base} />
                        <Spacer height={24} />
                        <TouchableOpacity style={[css.w_full, css.p_medium, css.items_center]}>
                            <Text style={[css.text_body, css.font_semibold, css.text_red_600]}>{t('screen_password.forgot_password')}</Text>
                        </TouchableOpacity>
                    </View>
                    <View style={[css.mt_auto, css.p_medium]}>
                        <GradientButton
                            title={t('screen_password.continue_register_card')}
                            gradientProps={disabled ? { type: 'secondary' } : { type: 'primary' }}
                            onPress={handleSubmit}
                        />
                    </View>
                </ScrollView>
            </SafeAreaView>
        </ImageBackground>
    );
};

export default DOPLoginScreen;
