import { injectable } from 'inversify';
import { Query } from '@src/domain/models/query';
import { HttpService } from '@core/service';
import { BASE_URL_CARD_DOP_API } from '@src/config';
import { CardDOPBaseResponse } from '@src/domain/entities/common/cardDOPBaseApi';
import { commonService } from '@src/infrastructure/network/networkService';
import { ValidateOcrDataReq, ValidateOcrDataRes } from '@src/domain/entities/card_dop/validateOcr';
import { IValidateOcrRepository } from '@src/domain/interfaces/card_dop/validateOcr';

@injectable()
export class ValidateOcrRepository
    extends HttpService
    implements IValidateOcrRepository {
    constructor() {
        super({ baseURL: BASE_URL_CARD_DOP_API });
    }

    async validateOcr<TParameter>(query: Query<TParameter>): Promise<CardDOPBaseResponse<ValidateOcrDataRes>> {
        const request = query.query as unknown as ValidateOcrDataReq;
        // console.log('\x1b[31m', 'validateOcr => request', request);
        const url = '/dop-validate-ocr';
        const response = await this.post(url, request, {
            headers: commonService.getHeader({ 'X-CHANNEL': 'mfe-dop-mobile' }),
        })
        return response.data as CardDOPBaseResponse<ValidateOcrDataRes>;
    }
}
