import { createSlice } from '@reduxjs/toolkit';
import { fetchRegisterUser } from '../thunk';

export interface IStateSlice {
    status: 'idle' | 'loading' | 'succeeded' | 'failed';
    error: string;
    registerStatus: boolean;
}

const initialState: IStateSlice = {
    status: 'idle',
    error: '',
    registerStatus: false,
};

const Slice = createSlice({
    name: 'dop_password',
    initialState,
    reducers: {
        setError: (state, { payload }) => {
            state.error = payload;
        },
        setStatus: (state, { payload }) => {
            state.status = payload;
        },
        setRegisterStatus: (state, { payload }) => {
            state.registerStatus = payload;
        },
    },
    extraReducers: (builder) => {
        builder
            .addCase(fetchRegisterUser.pending, (state) => {
                state.status = 'loading';
                state.error = '';
            })
            .addCase(fetchRegisterUser.rejected, (state, action) => {
                state.status = 'failed';
                state.error = action.error.message ?? 'Failed to fetch fetchRegisterUser';
            })
            .addCase(fetchRegisterUser.fulfilled, (state, { payload }) => {
                state.status = 'succeeded';
                if (!payload) {
                    state.error = 'Failed to fetch fetchRegisterUser because of payload undefined';
                    return;
                }
                state.error = '';

                const { data, resultCode, resultMessage } = payload;
                if (resultCode === '00') {
                    state.registerStatus = true;
                } else {
                    state.error = resultMessage;
                }
            });
    },
});

export default Slice;
