import {inject} from 'inversify';
import {TYPES} from '@src/di/types/types';
import {Query} from '@src/domain/models/query';
import { CardDOPBaseRequest } from '@src/domain/entities/common/cardDOPBaseApi';
import type { IVerifyTelcoOtpRepository } from '@src/domain/interfaces/card_dop/verifyTelcoOtp';
import { VerifyTelcoOtpDataReq } from '@src/domain/entities/card_dop/verifyTelcoOtp';

export class VerifyTelcoOtpHandler {
    private readonly _repository: IVerifyTelcoOtpRepository;

    constructor(
        @inject(TYPES.IVerifyTelcoOtpRepository)
        verifyTelcoOtpRepository: IVerifyTelcoOtpRepository
    ) {
        this._repository = verifyTelcoOtpRepository;
    }

    handle(query: Query<CardDOPBaseRequest<VerifyTelcoOtpDataReq>>) {
        return this._repository.verifyTelcoOtp(query);
    }
}
