import { DATE_FORMAT_DASH } from '@core/service';
import {
    DEFAULT_NO_LIMIT_EXPIRY_DATE_TEXT,
    DEFAULT_NO_LIMIT_EXPIRY_DATE,
    DATE_FORMAT_SLASH,
} from '@src/config';
import { HVDocumentDetails } from '@src/domain/entities/hyperV/ekyc';
import moment from 'moment';
const extractDayMonth = (date: string) => {
    return moment(date, DATE_FORMAT_DASH).format('DD-MM');
};
export const extractBirthDayExpireDayFromDocument = (
    document: HVDocumentDetails,
) => {
    const { dateOfBirth, dateOfExpiry, idBackMrzDOB, idBackMrzDOE } = document;

    if (
        idBackMrzDOB &&
        idBackMrzDOE &&
        extractDayMonth(idBackMrzDOB) === extractDayMonth(idBackMrzDOE)
    ) {
        return {
            birthDay: idBackMrzDOB,
            expireDay: idBackMrzDOE,
        };
    }
    if (
        dateOfBirth &&
        dateOfExpiry &&
        extractDayMonth(dateOfBirth) === extractDayMonth(dateOfExpiry)
    ) {
        return {
            birthDay: dateOfBirth,
            expireDay: dateOfExpiry,
        };
    }
    if (
        dateOfExpiry?.toUpperCase() === DEFAULT_NO_LIMIT_EXPIRY_DATE_TEXT.DOCUMENT
    ) {
        return {
            birthDay: dateOfBirth,
            expireDay: DEFAULT_NO_LIMIT_EXPIRY_DATE,
        };
    }
    if (idBackMrzDOE === DEFAULT_NO_LIMIT_EXPIRY_DATE) {
        return {
            birthDay: idBackMrzDOB,
            expireDay: DEFAULT_NO_LIMIT_EXPIRY_DATE,
        };
    }
    return {};
};
