import { injectable } from 'inversify';
import { Query } from '@src/domain/models/query';
import { HttpService } from '@core/service';
import { BASE_URL_CARD_DOP_API } from '@src/config';
import { CardDOPBaseResponse } from '@src/domain/entities/common/cardDOPBaseApi';
import { commonService } from '@src/infrastructure/network/networkService';
import { GetCareersPositionsDataReq, GetCareersPositionsDataRes } from '@src/domain/entities/card_dop/getCareersPositions';
import { IGetCareersPositionsRepository } from '@src/domain/interfaces/card_dop/getCareersPositions';

@injectable()
export class GetCareersPositionsRepository extends HttpService implements IGetCareersPositionsRepository {
    constructor() {
        super({ baseURL: BASE_URL_CARD_DOP_API });
    }

    async getCareersPositions<TParameter>(query: Query<TParameter>): Promise<CardDOPBaseResponse<GetCareersPositionsDataRes>> {
        const request = query.query as unknown as GetCareersPositionsDataReq;
        const url = '/dop-get-careers-positions';
        const response = await this.post(url, request, {
            headers: commonService.getHeader({ 'X-CHANNEL': 'mfe-dop-mobile' }),
        });
        return response.data as CardDOPBaseResponse<GetCareersPositionsDataRes>;
    }
}
