import { inject } from 'inversify';
import { TYPES } from '@src/di/types/types';
import { Query } from '@src/domain/models/query';
import { CardDOPBaseRequest } from '@src/domain/entities/common/cardDOPBaseApi';
import { ValidateOcrDataReq } from '@src/domain/entities/card_dop/validateOcr';
import type { IValidateOcrRepository } from '@src/domain/interfaces/card_dop/validateOcr';

export class ValidateOcrHandler {
    private readonly _repository: IValidateOcrRepository;

    constructor(
        @inject(TYPES.IValidateOcrRepository)
        validateOcrRepository: IValidateOcrRepository
    ) {
        this._repository = validateOcrRepository;
    }

    handle(query: Query<CardDOPBaseRequest<ValidateOcrDataReq>>) {
        return this._repository.validateOcr(query);
    }
}
