import React, { forwardRef, useState } from 'react';
import { TextInput, TouchableOpacity } from 'react-native';
import { FormInputProps, IEye, IEyeClose, MaterialTextInput } from '@core/ui';

interface PasswordInputProps extends Partial<FormInputProps> {}

const PasswordInput = forwardRef<TextInput | null, Partial<PasswordInputProps>>((props, ref) => {
    const [showPassword, setShowPassword] = useState(true);

    const onRightIconPress = () => {
        setShowPassword((prev) => !prev);
    };

    return (
        <MaterialTextInput
            label={'Mật khẩu'}
            autoFocus={false}
            inputMode={'text'}
            secureTextEntry={showPassword}
            rightIcon={() => <TouchableOpacity onPress={onRightIconPress}>{showPassword ? <IEye /> : <IEyeClose />}</TouchableOpacity>}
            {...props}
        />
    );
});

export default PasswordInput;
