import { injectable } from 'inversify';
import { Query } from '@src/domain/models/query';
import { HttpService } from '@core/service';
import { BASE_URL_CARD_DOP_API } from '@src/config';
import { CardDOPBaseResponse } from '@src/domain/entities/common/cardDOPBaseApi';
import { commonService } from '@src/infrastructure/network/networkService';
import { IBiometricInfoRepository } from '@src/domain/interfaces/card_dop/biometricInfo';
import { BiometricInfoDataReq, BiometricInfoDataRes } from '@src/domain/entities/card_dop/biometricInfo';

@injectable()
export class BiometricInfoRepository
    extends HttpService
    implements IBiometricInfoRepository {
    constructor() {
        super({ baseURL: BASE_URL_CARD_DOP_API });
    }

    async biometricInfo<TParameter>(query: Query<TParameter>): Promise<CardDOPBaseResponse<BiometricInfoDataRes>> {
        const request = query.query as unknown as BiometricInfoDataReq;
        const url = '/biometric-info';
        const response = await this.post(url, request, {
            headers: commonService.getHeader({ 'X-CHANNEL': 'mfe-dop-mobile' }),
        })        
        return response.data as CardDOPBaseResponse<BiometricInfoDataRes>;
    }
}
