import { createSlice } from '@reduxjs/toolkit';
import { fetchDopCVP, fetchRequestTelcoOtp, fetchVerifyTelcoOtp } from '../thunk';
import { RequestOtpDataRes } from '@src/domain/entities/card_dop/requestTelcoOtp';
import { CardDOPBaseResponse } from '@src/domain/entities/common/cardDOPBaseApi';
import { VerifyOtpResponse } from '@core/ui';
import { Attributes } from '@src/domain/entities/cms/dop/dopCVP';

export interface IStateCardSlice {
    status: 'idle' | 'loading' | 'succeeded' | 'failed';
    error: string;
    phone: string;
    telcoRequestId: string;
    mobileBranch: string;
    leadId: string;
    requestOTPStatus: string;
    verifyOTPRes?: CardDOPBaseResponse<VerifyOtpResponse>;
    token?: string;
    id: number;
    attributes: Attributes;
}

const initialState: IStateCardSlice = {
    status: 'idle',
    error: '',
    phone: '',

    telcoRequestId: '',
    mobileBranch: '',
    leadId: '',
    requestOTPStatus: '',
    verifyOTPRes: {} as CardDOPBaseResponse<VerifyOtpResponse>,
    id: -1,
    attributes: {} as Attributes,
};

const cardSlice = createSlice({
    name: 'CVPSlice',
    initialState,
    reducers: {
        setError: (state, { payload }) => {
            state.error = payload;
        },
        setStatus: (state, { payload }) => {
            state.status = payload;
        },
        setPhone: (state, { payload }) => {
            state.phone = payload;
        },
    },
    extraReducers: (builder) => {
        builder
            // -------------------------------------------------
            // fetchRequestTelcoOtp
            // -------------------------------------------------
            .addCase(fetchRequestTelcoOtp.pending, (state) => {
                state.status = 'loading';
                state.error = '';
            })
            .addCase(fetchRequestTelcoOtp.rejected, (state, action) => {
                state.status = 'failed';
                state.error = action.error.message ?? 'Failed to fetch fetchRequestTelcoOtp';
            })
            .addCase(fetchRequestTelcoOtp.fulfilled, (state, { payload }) => {
                state.status = 'succeeded';
                if (!payload) {
                    state.error = 'Failed to fetch fetchRequestTelcoOtp because of payload undefined';
                    return;
                }
                state.error = '';

                const { data, resultCode, resultMessage } = payload;
                if (resultCode === '00' && data?.leadId) {
                    state.leadId = data.leadId;
                    state.mobileBranch = data.mobileBranch;
                    state.telcoRequestId = data.telcoRequestId;
                    state.requestOTPStatus = data.status;
                } else {
                    state.error = resultMessage;
                }
            })

            // -------------------------------------------------
            // fetchVerifyTelcoOtp
            // -------------------------------------------------
            .addCase(fetchVerifyTelcoOtp.pending, (state) => {
                state.status = 'loading';
                state.error = '';
            })
            .addCase(fetchVerifyTelcoOtp.rejected, (state, action) => {
                state.status = 'failed';
                state.error = action.error.message ?? 'Failed to fetch fetchVerifyTelcoOtp';
            })
            .addCase(fetchVerifyTelcoOtp.fulfilled, (state, { payload }) => {
                state.status = 'succeeded';
                if (!payload) {
                    state.error = 'Failed to fetch fetchVerifyTelcoOtp because of payload undefined';
                    return;
                }
                state.error = '';
                const { data, resultCode, resultMessage } = payload;
                if (resultCode === '00' && data) {
                    // state.verifyOTPRes = payload;
                } else {
                    state.error = resultMessage;
                }
            })
            // -------------------------------------------------
            // fetchDopCVP
            // -------------------------------------------------
            .addCase(fetchDopCVP.pending, (state) => {
                state.status = 'loading';
                state.error = '';
            })
            .addCase(fetchDopCVP.rejected, (state, action) => {
                state.status = 'failed';
                state.error = action.error.message ?? 'Failed to fetch fetchDopCVP';
            })
            .addCase(fetchDopCVP.fulfilled, (state, { payload }) => {
                state.status = 'succeeded';
                if (!payload) {
                    state.error = 'Failed to fetch fetchDopCVP because of payload undefined';
                    return;
                }
                state.error = '';
                if (payload?.data.length > 0) {
                    state.attributes = payload?.data[0]?.attributes;
                }
            });
    },
});

export default cardSlice;
