import { inject } from 'inversify';
import { TYPES } from '@src/di/types/types';
import { Query } from '@src/domain/models/query';
import { CardDOPBaseRequest } from '@src/domain/entities/common/cardDOPBaseApi';
import type { IBiometricInfoRepository } from '@src/domain/interfaces/card_dop/biometricInfo';
import { BiometricInfoDataReq } from '@src/domain/entities/card_dop/biometricInfo';

export class BiometricInfoHandler {
    private readonly _repository: IBiometricInfoRepository;

    constructor(
        @inject(TYPES.IBiometricInfoRepository)
        biometricInfoRepository: IBiometricInfoRepository
    ) {
        this._repository = biometricInfoRepository;
    }

    handle(query: Query<CardDOPBaseRequest<BiometricInfoDataReq>>) {
        return this._repository.biometricInfo(query);
    }
}
