import React, { useRef } from 'react';
import {
    ActionButton,
    BottomSheet,
    BottomSheetManager,
    BottomSheetRef,
    GradientButton,
    IS_IOS,
    LoadingBlockerView,
    MaterialTextInputPropsMethod,
    PinInput,
    PortalManager,
    Spacer,
    Text,
} from '@core/ui';
import { Keyboard, TextInput, View } from 'react-native';

import useCSS from '@src/presentation/style';
import { useTranslation } from 'react-i18next';
import ContentPhone from './ContentPhone';
import { useDispatch, useSelector } from '@src/lib/redux';
import CVPSlice from '@src/presentation/dop_cvp/redux/CVPSlice';
import { fetchRequestTelcoOtp, fetchVerifyTelcoOtp } from '../thunk';
import { CardDOPBaseRequest, CardDOPBaseResponse } from '@src/domain/entities/common/cardDOPBaseApi';
import { RequestOtpDataReq, RequestOtpDataRes } from '@src/domain/entities/card_dop/requestTelcoOtp';
import { VerifyTelcoOtpDataReq, VerifyTelcoOtpDataRes } from '@src/domain/entities/card_dop/verifyTelcoOtp';
import { MainStackNavigationProp, MainStackParamList } from '@src/presentation/navigation/MainNavigator';
import { useNavigation } from '@react-navigation/native';
import { ELIGIBLE_CARD } from '@src/config';
import { useCustomNavigation } from '@src/hooks/useCustomNavigation';
import { selectCardActive } from '@src/presentation/dop_home/DOPHomeSelector';
import { selectAttributes } from '../redux/CVPSelector';

interface IInput extends TextInput, MaterialTextInputPropsMethod { }

const OpendCardButton = () => {
    const { t } = useTranslation(['common']);
    const { t: t2 } = useTranslation(['card']);
    const css = useCSS();
    const navigation = useNavigation<MainStackNavigationProp>();
    const { navigate } = useCustomNavigation();
    const refBSInput = useRef<BottomSheetRef>(null);
    const refBSOTP = useRef<BottomSheetRef>(null);
    const dispatch = useDispatch();
    const cardActive = useSelector(selectCardActive);
    const productCode = cardActive?.productCode;
    const attributes = useSelector(selectAttributes);

    const handleSubmit = (phone: string) => {
        refBSInput?.current?.close();
        dispatch(CVPSlice.actions.setPhone(phone));

        dispatch(fetchRequestTelcoOtp({ phone, productCode } as CardDOPBaseRequest<RequestOtpDataReq>['data'])).then((res) => {
            if ((res?.payload as CardDOPBaseResponse<RequestOtpDataRes>)?.resultCode === '00') {
                PortalManager.dismissAll();
                const data = (res?.payload as CardDOPBaseResponse<RequestOtpDataRes>)?.data;

                BottomSheetManager.show({
                    render: (portalId) => (
                        <BottomSheet
                            ref={refBSOTP}
                            id={portalId}
                            safeAreaBottomOffset={IS_IOS ? 370 : 0}
                            snapPoints={['70%']}
                            title={t('bs_title_otp')}
                            description={t('bs_desc_otp', { phoneNumber: phone.slice(-3) })}>
                            <View style={[css.items_center]}>
                                <PinInput cellCount={6} onChange={(otp) => handleValueChangeOTP(otp, data)} />
                            </View>
                            <Spacer height={32} />
                            <ActionButton title={t('bs_otp_resend')} type='error' onPress={handleResendOTP} />
                        </BottomSheet>
                    ),
                });
            }
        });
    };

    const handleValueChangeOTP = (otp: string, data: CardDOPBaseResponse<RequestOtpDataRes>['data']) => {
        const payload = {
            otp,
            leadId: data.leadId,
            mobileBranch: data.mobileBranch,
            telcoRequestId: data.telcoRequestId,
        };

        if (otp.length >= 6) {
            PortalManager.present(() => <LoadingBlockerView containerStyle={{ backgroundColor: 'rgba(255,255,255,0.5)', zIndex: 100000 }} />);

            dispatch(fetchVerifyTelcoOtp(payload as CardDOPBaseRequest<VerifyTelcoOtpDataReq>['data'])).then((res) => {
                PortalManager.dismissAll();
                const resp = res?.payload as CardDOPBaseResponse<VerifyTelcoOtpDataRes>;
                if (resp?.resultCode === '00') {
                    Keyboard.dismiss();
                    refBSOTP?.current?.close();
                    handleNextAction(resp?.data?.next);
                    // navigation.navigate('EKYC_identity_card');
                    // navigation.navigate('DOP_card_step1');
                }
            });
        }
    };
    const handleNextAction = (next: keyof typeof ELIGIBLE_CARD) => {
        if (next || next in ELIGIBLE_CARD) {
            const page = ELIGIBLE_CARD[next];
            navigate(page);
            return;
        }
        navigation.navigate('EKYC_identity_card');
    };
    const handleResendOTP = () => {
        // TODO: chưa có api
    };

    return (
        <>
            <GradientButton
                title={attributes?.cta_button?.text}
                gradientProps={{ type: 'primary' }}
                onPress={() => {
                    BottomSheetManager.show({
                        render: (portalId) => (
                            <BottomSheet
                                ref={refBSInput}
                                id={portalId}
                                title={t('bs_title_phone')}
                                safeAreaBottomOffset={IS_IOS ? 370 : 0}
                                snapPoints={['70%']}>
                                <ContentPhone onSubmit={(phone) => handleSubmit(phone)} />
                            </BottomSheet>
                        ),
                    });
                }}
            />
        </>
    );
};

export default OpendCardButton;
