import { createSlice } from '@reduxjs/toolkit';
import { fetchAuthUser, fetchGetAuthPublicKey } from '../thunk';
import { Acct } from '@src/domain/entities/card_dop/authUser';

export interface IStateSlice {
    status: 'idle' | 'loading' | 'succeeded' | 'failed';
    error: string;
    listCreditCard: Array<Acct>;
    publicKey: string;
}

const initialState: IStateSlice = {
    status: 'idle',
    error: '',
    listCreditCard: [],
    publicKey: '',
};

const Slice = createSlice({
    name: 'dop_password',
    initialState,
    reducers: {
        setError: (state, { payload }) => {
            state.error = payload;
        },
        setStatus: (state, { payload }) => {
            state.status = payload;
        },
    },
    extraReducers: (builder) => {
        builder
            .addCase(fetchGetAuthPublicKey.pending, (state) => {
                state.status = 'loading';
                state.error = '';
            })
            .addCase(fetchGetAuthPublicKey.rejected, (state, action) => {
                state.status = 'failed';
                state.error = action.error.message ?? 'Failed to fetch fetchGetAuthPublicKey';
            })
            .addCase(fetchGetAuthPublicKey.fulfilled, (state, { payload }) => {
                state.status = 'succeeded';
                if (!payload) {
                    state.error = 'Failed to fetch fetchGetAuthPublicKey because of payload undefined';
                    return;
                }
                state.error = '';

                const { data, resultCode, resultMessage } = payload;
                if (resultCode === '00') {
                    state.publicKey = data?.publicKey || '';
                } else {
                    state.error = resultMessage;
                }
            })
            .addCase(fetchAuthUser.pending, (state) => {
                state.status = 'loading';
                state.error = '';
            })
            .addCase(fetchAuthUser.rejected, (state, action) => {
                state.status = 'failed';
                state.error = action.error.message ?? 'Failed to fetch fetchAuthUser';
            })
            .addCase(fetchAuthUser.fulfilled, (state, { payload }) => {
                state.status = 'succeeded';
                if (!payload) {
                    state.error = 'Failed to fetch fetchAuthUser because of payload undefined';
                    return;
                }
                state.error = '';

                const { data, resultCode, resultMessage } = payload;
                if (resultCode === '00') {
                    state.listCreditCard = data?.accts || [];
                } else {
                    state.error = resultMessage;
                }
            });
    },
});

export default Slice;
