import React, { FC, useEffect, useRef, useState } from 'react';
import {
    Alert,
    Animated,
    Dimensions,
    Image,
    KeyboardAvoidingView,
    SafeAreaView,
    ScrollView,
    TouchableOpacity,
    View,
    findNodeHandle,
    UIManager,
} from 'react-native';
import useCSS from '@src/presentation/style/index';
import OpendCardButton from './components/OpenCardButton';
import { MainStackNavigationProp } from '../navigation/MainNavigator';
import { useNavigation } from '@react-navigation/native';
import { IS_IOS } from '@core/service';
import { ActionButton, CheckBox, GradientContainer, LoadingBlockerView, SimpleHeader, Spacer, Text, useTheme } from '@core/ui';
import { useDispatch, useSelector } from '@src/lib/redux';
import { selectStatus, selectError, selectAttributes } from '@src/presentation/dop_cvp/redux/CVPSelector';
import { SelectedTrackType, Video } from 'react-native-video';
import { SCREEN_HEIGHT } from '@src/utils/size';
import { fetchDopCVP } from './thunk';
import { DopCVPDataRes, Item, Item2, Item3 } from '@src/domain/entities/cms/dop/dopCVP';
import getImg from '@src/utils/getImg';
import { useTranslation } from 'react-i18next';
import { selectCardActive } from '../dop_home/DOPHomeSelector';
import TnCText from '../components/text/TnCText';
import BottomSheetPDF from '../components/bottomSheetPDF';
import HighlightString from '../components/text/HighlightString';
import cvpSlice from '@src/presentation/dop_cvp/redux/CVPSlice';

const { width } = Dimensions.get('window');
const CARD_WIDTH = width * 0.85; // Giảm chiều rộng để hiển thị một phần item tiếp theo
const SPACING = 16; // Khoảng cách giữa các item

const DOPCVPScreen = () => {
    const dispatch = useDispatch();
    const css = useCSS();
    const { theme } = useTheme();
    const { t } = useTranslation(['cvp']);
    const navigation = useNavigation<MainStackNavigationProp>();
    const status = useSelector(selectStatus);
    const error = useSelector(selectError);

    const [muted, setMuted] = useState(false);

    const attributes = useSelector(selectAttributes);

    const scrollViewContainerRef = useRef<ScrollView>(null);
    const contentDetailRef = useRef<View>(null);

    const promotionListRef = useRef(null);
    const scrollX = useRef(new Animated.Value(0)).current;

    const cardActive = useSelector(selectCardActive);

    const [checked, setChecked] = useState(false);

    const [openTnC, setOpenTnC] = useState(false);

    const handleScrollTo = () => {
        if (!contentDetailRef.current || !scrollViewContainerRef.current) return;

        const nodeHandle = findNodeHandle(contentDetailRef.current);
        if (!nodeHandle) return;

        UIManager.measure(nodeHandle, (_x, _y, _width, _height, _pageX, pageY) => {
            scrollViewContainerRef.current?.scrollTo({ y: pageY, animated: true });
        });
    };

    useEffect(() => {
        if (error) {
            Alert.alert('Thông báo', error);
        }
    }, [error]);

    useEffect(() => {
        dispatch(fetchDopCVP(cardActive?.productCode)).then((res) => {
            const data = (res?.payload as DopCVPDataRes)['data'];
            console.log('thieuvq3_________dop cvp: ', data[0]?.attributes);
        });
    }, []);

    return (
        <>
            <KeyboardAvoidingView behavior={IS_IOS ? 'padding' : 'height'} style={[css.flex_1]}>
                <ScrollView ref={scrollViewContainerRef} style={[{ minHeight: SCREEN_HEIGHT, flex: 1 }]}>
                    <View style={[css.relative, { height: SCREEN_HEIGHT }]}>
                        <Video
                            source={{ uri: attributes?.media_url }}
                            style={[css.w_full, css.h_full]}
                            resizeMode='cover'
                            muted={muted}
                            repeat
                            selectedAudioTrack={{ type: SelectedTrackType.SYSTEM }}
                        />
                        <View style={[css.absolute, , { bottom: '30%', left: 8, right: 8 }]}>
                            <View style={[css.row, css.justify_center, css.mb_medium]}>
                                <TouchableOpacity style={[css.row, css.items_center]} onPress={handleScrollTo}>
                                    <Text style={[css.text_subheadline, css.font_semibold, css.text_white]}>{t('benefit_details')}</Text>
                                    <Image
                                        source={getImg('/assets/images/icons/icon_arrow_double_down_white.png')}
                                        resizeMode='contain'
                                        style={[css.shrink_0, css.w_xLarge, css.h_xLarge, css.ml_small]}
                                    />
                                </TouchableOpacity>
                            </View>
                            <View style={[css.rounded_medium, { backgroundColor: 'rgba(255,255,255,0.8)' }]}>
                                <View style={[css.row]}>
                                    {attributes?.features?.length > 0 &&
                                        attributes?.features?.map?.(
                                            (item, index) =>
                                                item?.is_active && (
                                                    <View key={`feature-${item?.id}`} style={[css.flex_1, css.pv_regular, css.ph_base]}>
                                                        <Image
                                                            source={{ uri: item?.image_url }}
                                                            style={[
                                                                css.mh_auto,
                                                                { width: theme.Scaling.hs(72), height: theme.Scaling.vs(72), objectFit: 'contain' },
                                                            ]}
                                                        />
                                                        <Text style={[css.text_subheadline, css.font_semibold, css.text_black, css.text_center]}>
                                                            {item?.description}
                                                        </Text>
                                                    </View>
                                                ),
                                        )}
                                </View>
                            </View>
                        </View>
                    </View>
                    <View style={[css.bg_yellow_100]} ref={contentDetailRef}>
                        {attributes?.promotions?.data?.attributes?.is_active ? (
                            <>
                                <Text style={[css.text_large_title, css.font_semibold, css.text_black, css.m_medium]}>
                                    {attributes?.promotions?.data?.attributes?.title}
                                </Text>
                                <ScrollView
                                    horizontal
                                    ref={promotionListRef}
                                    pagingEnabled={false} // Tắt pagingEnabled để có hiệu ứng trượt mượt
                                    showsHorizontalScrollIndicator={false}
                                    onScroll={Animated.event([{ nativeEvent: { contentOffset: { x: scrollX } } }], {
                                        useNativeDriver: false,
                                    })}
                                    snapToInterval={CARD_WIDTH + SPACING}
                                    decelerationRate='fast'
                                    scrollEventThrottle={SPACING}>
                                    <View style={[css.row]}>
                                        {attributes?.promotions?.data?.attributes?.items?.length > 0 &&
                                            attributes?.promotions?.data?.attributes?.items?.map?.((item, index) => {
                                                if (item?.is_active) {
                                                    return <SectionItem1 key={`promotion-${item?.id}`} item={item} index={index} />;
                                                }
                                            })}
                                    </View>
                                </ScrollView>
                            </>
                        ) : null}
                        {attributes?.games_and_promotions?.data?.attributes?.is_active ? (
                            <>
                                <Spacer height={56} />
                                <Text style={[css.text_large_title, css.font_semibold, css.text_black, css.mh_medium, css.mt_medium]}>
                                    {attributes?.games_and_promotions?.data?.attributes?.title}
                                </Text>
                                <View style={[css.mh_medium, css.mt_xLarge]}>
                                    {attributes?.games_and_promotions?.data?.attributes?.items?.length > 0 &&
                                        attributes?.games_and_promotions?.data?.attributes?.items?.map?.((item, index) => {
                                            if (item?.is_active) {
                                                return <SectionItem2 key={`games_and_promotion-${item?.id}`} item={item} index={index} />;
                                            }
                                        })}
                                </View>
                            </>
                        ) : null}
                        {attributes?.questionnaire?.data?.attributes?.is_active ? (
                            <>
                                <Spacer height={64} />
                                <Text style={[css.text_large_title, css.font_semibold, css.text_black, css.mh_medium, css.mt_medium]}>
                                    {attributes?.questionnaire?.data?.attributes?.title}
                                </Text>
                                <View style={[css.mh_medium]}>
                                    {attributes?.questionnaire?.data?.attributes?.items?.map?.((item, index) => {
                                        if (item?.is_active) {
                                            return <SectionItem3 key={`key-questionnaire-${index}`} item={item} index={index} />;
                                        }
                                    })}
                                </View>
                            </>
                        ) : null}
                        <Spacer height={200} />
                    </View>
                </ScrollView>

                <View style={[css.absolute, { top: 0, left: 0, right: 0 }]}>
                    <SafeAreaView style={[]}>
                        <SimpleHeader
                            allowGoBack
                            onBackPress={() => {
                                navigation.goBack();
                                dispatch(cvpSlice.actions.setError(''));
                            }}
                        />
                    </SafeAreaView>
                </View>
                <View style={[css.absolute, css.p_medium, { bottom: 0, left: 0, right: 0, backgroundColor: 'rgba(255,255,255, 0.5)' }]}>
                    <SafeAreaView style={[]}>
                        <View style={[css.row]}>
                            <CheckBox title='' size='large' checked={checked} onPress={() => setChecked((prev) => !prev)} />
                            <View style={[css.flex_1]}>
                                <TnCText
                                    style={[css.text_subheadline, css.text_black]}
                                    text={t(`${attributes?.tnc_text?.text}`, {
                                        highlighted: attributes?.tnc_text?.highlight,
                                    })}
                                    onPress={() => setOpenTnC(true)}
                                />
                            </View>
                        </View>
                        <View style={[css.mt_medium, css.mh_medium]}>
                            {checked ? (
                                <OpendCardButton />
                            ) : (
                                <ActionButton
                                    state={'disabled'}
                                    title={attributes?.cta_button?.text}
                                    style={{ height: theme.Size.Vertical.ExtraLarge, paddingHorizontal: 0, marginHorizontal: 0, borderRadius: 99999 }}
                                />
                            )}
                        </View>
                    </SafeAreaView>
                </View>
            </KeyboardAvoidingView>

            <BottomSheetPDF
                title={attributes?.tnc_text?.title_bottom_sheet}
                show={openTnC}
                onClose={() => setOpenTnC(false)}
                link={attributes?.tnc_text?.highlight_url}
            />

            {status === 'loading' ? <LoadingBlockerView containerStyle={{ backgroundColor: 'rgba(255,255,255,0.5)', zIndex: 100000 }} /> : null}
        </>
    );
};

const SectionItem1: FC<{ item: Item; index: number }> = ({ item, index }) => {
    const css = useCSS();
    const { theme } = useTheme();
    return (
        <GradientContainer
            colorList={theme.GradientColors.Horizontal}
            style={[
                css.rounded_medium,
                css.overflow_hidden,
                css.shrink_0,
                css.mr_medium,
                index === 0 ? css.ml_medium : null,
                { width: theme.Scaling.hs(CARD_WIDTH) },
            ]}>
            <View>
                <Image source={{ uri: item?.image_url }} resizeMode='cover' style={[css.w_full, { height: theme.Scaling.vs(220) }]} />
                <View style={[css.pv_medium, css.ph_xLarge]}>
                    <Text style={[css.text_center, css.text_body, css.font_medium, css.text_white]}>{item?.description}</Text>
                </View>
            </View>
        </GradientContainer>
    );
};

const SectionItem2: FC<{ item: Item2; index: number }> = ({ item, index }) => {
    const css = useCSS();
    return (
        <View style={[css.row, css.items_center, index > 0 ? css.mt_medium : null]}>
            <Image source={{ uri: item.icon_url }} resizeMode='contain' style={[css.w_xxxLarge, css.h_xxxLarge, css.shrink_0, css.mr_medium]} />
            <View style={[css.flex_1]}>
                <Text style={[css.text_body, css.font_medium, css.text_black]}>{item?.text}</Text>
            </View>
        </View>
    );
};

const SectionItem3: FC<{ item: Item3; index: number }> = ({ item, index }) => {
    const css = useCSS();
    const { t } = useTranslation(['cvp']);
    const [show, setShow] = useState(false);
    return (
        <View style={[css.pv_medium, index > 0 ? [css.border_t_1, css.border_t_neutral_400] : null]}>
            <TouchableOpacity onPress={() => setShow((prev) => !prev)}>
                <View style={[css.row, css.items_center]}>
                    <Image
                        source={{ uri: show ? item?.active_icon_url : item?.inactive_icon_url }}
                        resizeMode='contain'
                        style={[css.shrink_0, css.w_xxLarge, css.h_xxLarge]}
                    />
                    <Text style={[css.flex_1, css.mh_base, css.text_body, css.text_black, css.font_regular]}>{item?.question}</Text>

                    <Image
                        source={getImg('/assets/images/icons/right_arrow.png')}
                        resizeMode='contain'
                        style={[css.shrink_0, css.w_regular, css.h_regular, { transform: [{ rotateZ: show ? '90deg' : '0deg' }] }]}
                    />
                </View>
            </TouchableOpacity>
            {/* {show ? <Text style={[css.mt_base, css.text_subheadline, { lineHeight: 21 }]}>{item?.answer}</Text> : null} */}
            {show ? (
                <HighlightString
                    style={[css.mt_base, css.text_subheadline, { lineHeight: 21 }]}
                    text={`${t(item?.answer, {
                        firstHighlight: item?.first_highlight,
                        secondHighlight: item?.second_highlight,
                        thirdHighlight: item?.third_highlight,
                        fourthHighlight: item?.fourth_highlight,
                        fifthHighlight: item?.fifth_highlight,
                    })}`}
                    urls={{
                        firstHighlight: item?.first_highlight_url || '',
                        secondHighlight: item?.second_highlight_url || '',
                        thirdHighlight: item?.third_highlight_url || '',
                        fourthHighlight: item?.fourth_highlight_url || '',
                        fifthHighlight: item?.fifth_highlight_url || '',
                    }}
                />
            ) : null}
        </View>
    );
};

export default DOPCVPScreen;
