export const encryptPasswordRSA = (password: string, keyPem: string): string => {    
    console.log('\x1b[31m thieuvq3 encryptPasswordRSA : ', forge.util.encodeUtf8(password));
    console.log('\x1b[31m thieuvq3 encryptPasswordRSA keyPem: ', keyPem);
    const publicKey = forge.pki.publicKeyFromPem(keyPem);
    const encrypted = publicKey.encrypt(forge.util.encodeUtf8(password));
    
    return forge.util.encode64(encrypted); // Chuyển thành base64 để gửi đi
};

export const formatPublicKeyPEM = (publicKey: string) => {
    const pemHeader = "-----BEGIN PUBLIC KEY-----\n";
    const pemFooter = "\n-----END PUBLIC KEY-----";
    
    return pemHeader + publicKey + pemFooter;
};