import React, { useEffect, useReducer, useState } from 'react';
import { SafeAreaView, ScrollView, ImageBackground, View, Image, Alert, KeyboardTypeOptions, KeyboardAvoidingView } from 'react-native';
import { ActionButton, GradientButton, LoadingBlockerView, MaterialTextInput, SimpleHeader, Spacer, Text, useTheme } from '@core/ui';
import useCSS from '@src/presentation/style';

import { useNavigation } from '@react-navigation/native';
import { MainStackNavigationProp } from '@src/presentation/navigation/MainNavigator';
import { useDispatch } from '@src/lib/redux';
import { useTranslation } from 'react-i18next';

import getImg from '@src/utils/getImg';
import { selectStatus, selectError } from '@src/presentation/dop_card/redux/cardSelector';

import cardSlice, { IStateCardSlice } from '@src/presentation/dop_card/redux/cardSlice';
import { selectDataPayload } from '@src/presentation/dop_card/redux/cardSelector';
import { validator } from '@src/utils/validator';
import { fetchCustomerInfoV2 } from './thunk';

import type { CardDOPBaseRequest, CardDOPBaseResponse } from '@src/domain/entities/common/cardDOPBaseApi';
import type { CustomerInfoV2DataReq, CustomerInfoV2DataRes } from '@src/domain/entities/card_dop/customerInfoV2';
import { formatMoney } from '@src/utils/currency';
import { IS_IOS } from '@core/service';
import { selectLeadId } from '../dop_cvp/redux/CVPSelector';
import { useSelector } from 'react-redux';

const DOPCardStep1Screen = () => {
    const css = useCSS();
    const dispatch = useDispatch();
    const navigation = useNavigation<MainStackNavigationProp>();
    const { t } = useTranslation(['validator']);
    const { theme } = useTheme();


    const leadId = useSelector(selectLeadId);
    const status = useSelector(selectStatus);
    // const error = useSelector(selectError);
    const dataPayload = useSelector(selectDataPayload);

    const [disabled, setDisabled] = useState(true);


    const [listErrorMessage, setListErrorMessage] = useReducer(
        (prev: Record<string, string | undefined | null>, next: Record<string, string | undefined | null>) => ({ ...prev, ...next }),
        {},
    );

    const inputList = [
        {
            key: 'email',
            value: '',
            label: 'Email của bạn',
            fn: (text: string) => handleChangeDataPayload('email', text),
            require: true,
            validator: (text: string) => validator.validateEmail(text),
            keyboardType: 'email-address',
        },
        {
            key: 'ref1MobilePhone',
            value: '',
            label: 'Số điện thoại người thân',
            fn: (text: string) => handleChangeDataPayload('ref1MobilePhone', text),
            require: true,
            validator: (text: string) => validator.validatePhoneNumber(text),
            keyboardType: 'phone-pad',
            maxLength: 10
        },
        {
            key: 'ref2MobilePhone',
            value: '',
            label: 'Số điện thoại người thân 2',
            fn: (text: string) => handleChangeDataPayload('ref2MobilePhone', text),
            require: true,
            validator: (text: string) => validator.validatePhoneNumber(text),
            keyboardType: 'phone-pad',
            maxLength: 10
        },
        {
            key: 'companyName',
            value: '',
            label: 'Tên công ty làm việc (Nếu có)',
            fn: (text: string) => handleChangeDataPayload('companyName', text),
            require: false,
            keyboardType: 'default',
        },
        {
            key: 'companyAddress',
            value: '',
            label: 'Địa chỉ công ty làm việc (Nếu có)',
            fn: (text: string) => handleChangeDataPayload('companyAddress', text),
            require: false,
            keyboardType: 'default',
        },
        {
            key: 'income',
            value: '',
            label: 'Thu nhập hàng tháng',
            fn: (text: string) => {
                const removeFormatValue = text.replace(/\D/g, '');
                handleChangeDataPayload('income', removeFormatValue);
            },
            require: true,
            keyboardType: 'number-pad',
        },
    ];

    const handleChangeDataPayload = (key: string, value: string) => {
        if (listErrorMessage[key]) {
            setListErrorMessage({ [key]: '' });
        }
        dispatch(cardSlice.actions.setDataPayload({ [key]: value }));
    };

    const handleValidate = () => {
        let isInvalid = false;
        inputList.forEach((item) => {
            if (item.require) {
                const result = item.validator?.(dataPayload?.[item?.key as keyof IStateCardSlice['dataPayload']]);
                console.log('result', result);
                if (result?.isInvalid) {
                    setListErrorMessage({ [item.key]: result.errors || '' });
                    if (isInvalid === false) {
                        isInvalid = true;
                    }
                } else {
                    setListErrorMessage({ [item.key]: '' });
                }
                if (dataPayload[item.key as keyof IStateCardSlice['dataPayload']]) {
                    return;
                }
            }
        });

        if (isInvalid) {
            return;
        }

        handleSubmit();
    };

    const handleSubmit = () => {
        dispatch(
            fetchCustomerInfoV2({
                leadId: leadId,
                email: dataPayload?.email,
                ref1MobilePhone: dataPayload?.ref1MobilePhone,
                ref2MobilePhone: dataPayload?.ref2MobilePhone,
                company: dataPayload.companyName,
                companyAddress: dataPayload?.companyAddress,
                income: dataPayload.income,
                licensePlate: dataPayload.licensePlate,
                licensePlateType: dataPayload.licensePlateType,
                ePassReferralCode: dataPayload.ePassReferralCode,
            } as CardDOPBaseRequest<CustomerInfoV2DataReq>['data']),
        ).then((res) => {
            const payload = res?.payload as CardDOPBaseResponse<CustomerInfoV2DataRes>;
            if (!payload) return;
            if (payload.resultCode === '00') {
                navigation.navigate('DOP_card_step2');
            } else {
                Alert.alert('Thông báo', payload.resultMessage || 'Có lỗi xảy ra');
            }
        });
    };

    useEffect(() => {
        const { email, ref1MobilePhone, ref2MobilePhone, income } = dataPayload;
        if (email && ref1MobilePhone && ref2MobilePhone && income) {
            setDisabled(false);
        } else {
            setDisabled(true);
        }
    }, [dataPayload?.email, dataPayload?.ref1MobilePhone, dataPayload?.ref2MobilePhone, dataPayload?.income]);



    // console.log('dataPayload', dataPayload);

    return (
        <KeyboardAvoidingView behavior={IS_IOS ? 'padding' : 'height'} style={[css.flex_1]}>
            <ImageBackground source={getImg('/assets/images/bg_body.jpg')} resizeMode='cover' style={{ flex: 1 }}>
                <SafeAreaView style={[css.flex_1]}>
                    <SimpleHeader
                        allowGoBack
                        title={`Phát hành thẻ tín dụng`}
                        onBackPress={() => {
                            navigation.goBack();
                        }}
                    />
                    {status === 'loading' ? <LoadingBlockerView containerStyle={{ backgroundColor: 'rgba(255,255,255,0.5)', zIndex: 100000 }} /> : null}
                    <ScrollView contentContainerStyle={[css.ph_medium]}>
                        <Spacer height={16} />
                        <Image
                            source={getImg('/assets/images/card_hdbank_visa_vietjet_air.png')}
                            style={{ width: theme.Scaling.hs(76), height: theme.Scaling.vs(112) }}
                        />
                        <Spacer height={24} />
                        <Text style={[css.page_title]}>Hãy cung cấp thông tin</Text>
                        <Text style={[css.page_sub_title, css.mt_base]}>Để nhận ngay thẻ HDBank Vietjet Platinum nhé!</Text>
                        <Spacer height={24} />
                        {inputList?.map((item, index) => (
                            <React.Fragment key={`key-${index}`}>
                                {index > 0 ? <Spacer height={16} /> : null}
                                <View>
                                    <MaterialTextInput
                                        keyboardType={item?.keyboardType as KeyboardTypeOptions}
                                        label={item?.label}
                                        value={
                                            item?.key === 'income'
                                                ? formatMoney(dataPayload?.[item?.key as keyof IStateCardSlice['dataPayload']])
                                                : dataPayload?.[item?.key as keyof IStateCardSlice['dataPayload']] || ''
                                        }
                                        onChangeText={item?.fn}
                                        maxLength={item?.maxLength}
                                    />
                                </View>
                                <Text style={[css.text_caption_100, css.text_red_600]}>{t(listErrorMessage[item.key] || '')}</Text>
                            </React.Fragment>
                        ))}

                        <View style={[css.mt_auto]}>
                            {disabled ? (
                                <ActionButton title={'Tiếp tục'} state='disabled' />
                            ) : (
                                <GradientButton title={'Tiếp tục'} gradientProps={{ type: 'primary' }} onPress={handleValidate} />
                            )}
                        </View>
                    </ScrollView>
                </SafeAreaView>
            </ImageBackground>
        </KeyboardAvoidingView>
    );
};

export default DOPCardStep1Screen;
