import { injectable } from 'inversify';
import { Query } from '@src/domain/models/query';
import { HttpService } from '@core/service';
import { BASE_URL_CARD_DOP_API } from '@src/config';
import { CardDOPBaseResponse } from '@src/domain/entities/common/cardDOPBaseApi';
import { commonService } from '@src/infrastructure/network/networkService';
import { IDopSubmitV2Repository } from '@src/domain/interfaces/card_dop/dopSubmitV2';
import { DopSubmitV2DataReq, DopSubmitV2DataRes } from '@src/domain/entities/card_dop/dopSubmitV2';

@injectable()
export class DopSubmitV2Repository
    extends HttpService
    implements IDopSubmitV2Repository {
    constructor() {
        super({ baseURL: BASE_URL_CARD_DOP_API });
    }

    async dopSubmitV2<TParameter>(query: Query<TParameter>): Promise<CardDOPBaseResponse<DopSubmitV2DataRes>> {
        const request = query.query as unknown as DopSubmitV2DataReq;
        const url = '/dop-submit-v2';
        const response = await this.post(url, request, {
            headers: commonService.getHeader({ 'X-CHANNEL': 'mfe-dop-mobile' }),
        })                
        console.log('\x1b[31m thieuvq3 response dop-submit-v2: ', response);
        return response.data as CardDOPBaseResponse<DopSubmitV2DataRes>;
    }
}
