import {inject} from 'inversify';
import {TYPES} from '@src/di/types/types';
import {Query} from '@src/domain/models/query';
import { CardDOPBaseRequest } from '@src/domain/entities/common/cardDOPBaseApi';
import type { IGetAuthPublicKeyRepository } from '@src/domain/interfaces/card_dop/getAuthPublicKey';
import { GetAuthPublicKeyDataReq } from '@src/domain/entities/card_dop/getAuthPublicKey';

export class GetAuthPublicKeyHandler {
    private readonly _repository: IGetAuthPublicKeyRepository;

    constructor(
        @inject(TYPES.IGetAuthPublicKeyRepository)
        getAuthPublicKeyRepository: IGetAuthPublicKeyRepository
    ) {
        this._repository = getAuthPublicKeyRepository;
    }

    handle(query: Query<CardDOPBaseRequest<GetAuthPublicKeyDataReq>>) {
        return this._repository.getAuthPublicKey(query);
    }
}
