export const validateOCRThunk = createAsyncThunk('ocr/validate', async (data?: CardDOPBaseRequest<ValidateOcrDataReq>['data']) => {
    console.log('\x1b[31m CvalidateOCRThunk', 'validateOCRThunk');
    const validateOCR = container.get<ValidateOcrHandler>(TYPES.ValidateOcrHandler);
    const validateOcrDataReq = store.getState().dop.validateOCRData;
    const biometricInfo = store.getState().ocr.biometricInfo
    // console.log('\x1b[31m phasdvalidateOCRThunk', JSON.stringify(validateOcrDataReq));


    const payload: ValidateOcrDataReq = {
        ...validateOcrDataReq, ...{
            leadId: store.getState().cvp.leadId,
            biometricExisted: biometricInfo?.data?.biometricExisted || false,
            partnerId: 'DOP',
            biometricKey: biometricInfo?.data?.biometricKey || '5a2ad4c0-8aba-48da-9b7c-726ad3af2cfa',
            biometricRate: '100'
        }
    }

    let payloadReq = commonService.getPayload<CardDOPBaseRequest<ValidateOcrDataReq>, ValidateOcrDataReq>({ data: { ...mockPayloadValidateOCR, leadId: store.getState().cvp.leadId } })
    const query = new Query<CardDOPBaseRequest<ValidateOcrDataReq>>({
        query: payloadReq
    })
    return await validateOCR.handle(query)
}
);
