import { injectable } from 'inversify';
import { CmsService } from '@core/service';
import { IDopCVPRepository } from '@src/domain/interfaces/cms/dop/dopCVP';
import { DopCVPDataRes } from '@src/domain/entities/cms/dop/dopCVP';

@injectable()
export class DopCVPRepository extends CmsService implements IDopCVPRepository {
    constructor() {
        super();
    }

    async getDopCVP(cvp_name: string): Promise<DopCVPDataRes> {
        try {
            const response = await this.get<DopCVPDataRes>('/common-long-form-cvps', {
                params: {
                    populate: 'deep',
                    'filters[cvp_name][$eq]': cvp_name,
                    locale: 'vi', // cần update chỗ này
                },
            });
            return (response.data as DopCVPDataRes) ?? null;
        } catch (error) {
            throw error;
        }
    }
}
